/// How the server counts characters in a line.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum PositionEncoding {
    Utf8,
    Utf16,
}

/// Line and character for a scalar offset. An offset past the end is the end.
pub fn to_lsp(text: &kate_text::Rope, at: kate_text::Offset, encoding: PositionEncoding) -> lsp_types::Position
/// Scalar offset for a position. A line past the end is the last line; a character past the line end is the line end.
pub fn from_lsp(text: &kate_text::Rope, position: lsp_types::Position, encoding: PositionEncoding) -> kate_text::Offset
